// Package sqlconst is the FF-SP2 pass for safe-primitives §7: the SQL argument of Exec, Query,
// QueryRow, Queue and their Context variants must be a constant or a CompiledSQL value, which only
// the report compiler can produce. Code generated by sqlc is exempt: its queries are constants.
// forbidigo cannot check argument kinds; go/types can.
//
// Tests and tier L (lab and tools) are not judged.
package sqlconst

import (
	"go/ast"
	"go/types"

	"golang.org/x/tools/go/analysis"

	"github.com/skenzeriq/activediq/tools/analyzers/policy"
	"github.com/skenzeriq/activediq/tools/analyzers/util"
)

const Name = "sqlconst"

var Analyzer = &analysis.Analyzer{
	Name: Name,
	Doc:  "FF-SP2 (safe-primitives §7): the SQL argument of Exec/Query/QueryRow/Queue must be a constant or a reportsql.CompiledSQL",
	Run:  run,
}

var sqlMethods = map[string]bool{
	"Exec": true, "ExecContext": true, "Query": true, "QueryContext": true, "QueryRow": true, "QueryRowContext": true,
	"Queue": true, "Prepare": true, "PrepareContext": true, "SendBatch": false,
}

// driverish says whether a receiver or declaring package is a SQL access type: pgx, database/sql, or
// the DBTX interface sqlc generates.
func driverish(pass *analysis.Pass, fn *types.Func) bool {
	sig, _ := fn.Type().(*types.Signature)
	if sig == nil || sig.Recv() == nil {
		return false
	}
	if fn.Pkg() != nil {
		p := fn.Pkg().Path()
		if p == "database/sql" || p == "github.com/jackc/pgx/v5" || p == "github.com/jackc/pgx/v5/pgxpool" || p == "github.com/jackc/pgx/v5/pgconn" {
			return true
		}
	}
	rt := sig.Recv().Type()
	if pt, ok := rt.(*types.Pointer); ok {
		rt = pt.Elem()
	}
	if n, ok := types.Unalias(rt).(*types.Named); ok {
		switch n.Obj().Name() {
		case "DBTX", "Tx", "Conn", "Pool", "DB", "Batch", "Querier", "Queryer", "Execer":
			// A project-defined access interface or wrapper: judged by its method shape below.
			return hasStringParam(sig)
		}
	}
	return false
}

func hasStringParam(sig *types.Signature) bool {
	for i := 0; i < sig.Params().Len(); i++ {
		if b, ok := sig.Params().At(i).Type().Underlying().(*types.Basic); ok && b.Info()&types.IsString != 0 {
			return true
		}
	}
	return false
}

func isCompiledSQL(pass *analysis.Pass, t types.Type) bool {
	n, ok := types.Unalias(t).(*types.Named)
	if !ok || n.Obj().Name() != "CompiledSQL" || n.Obj().Pkg() == nil {
		return false
	}
	return policy.Match(util.TypesPkgDir(pass, n.Obj().Pkg()), policy.Store+"/reportsql")
}

// forwards reports whether arg is a parameter of the enclosing function that passes it, unchanged, to
// the same-named method: the thin Exec/Query/QueryRow wrappers of the data-access package
// (internal/platform/store) that hide the pgx transaction. The SQL is then judged where the wrapper is
// called, because the wrapper's type (Tx) is itself an access type.
func forwards(pass *analysis.Pass, fd *ast.FuncDecl, fn *types.Func, arg ast.Expr) bool {
	id, ok := arg.(*ast.Ident)
	if !ok || fd == nil || fd.Name.Name != fn.Name() || !policy.Match(util.PkgDir(pass), policy.Store) {
		return false
	}
	used := pass.TypesInfo.Uses[id]
	// Only the wrapper's own SQL parameter: its first string-typed one, as in checkCall.
	for _, field := range fd.Type.Params.List {
		if len(field.Names) == 0 {
			continue
		}
		if b, ok := pass.TypesInfo.TypeOf(field.Type).Underlying().(*types.Basic); !ok || b.Info()&types.IsString == 0 {
			continue
		}
		return used != nil && pass.TypesInfo.Defs[field.Names[0]] == used
	}
	return false
}

func run(pass *analysis.Pass) (any, error) {
	for _, f := range pass.Files {
		if util.SkipFile(pass, f) || util.HasHeader(f, policy.SQLCHeader) {
			continue
		}
		for _, decl := range f.Decls {
			fd, _ := decl.(*ast.FuncDecl)
			ast.Inspect(decl, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				checkCall(pass, fd, call)
				return true
			})
		}
	}
	return nil, nil
}

func checkCall(pass *analysis.Pass, fd *ast.FuncDecl, call *ast.CallExpr) {
	fn := util.Callee(pass, call)
	if fn == nil || !sqlMethods[fn.Name()] || !driverish(pass, fn) {
		return
	}
	sig := fn.Type().(*types.Signature)
	// The SQL argument is the first string-typed parameter.
	for i := 0; i < sig.Params().Len() && i < len(call.Args); i++ {
		pt := sig.Params().At(i).Type()
		if b, ok := pt.Underlying().(*types.Basic); !ok || b.Info()&types.IsString == 0 {
			continue
		}
		arg := call.Args[i]
		tv := pass.TypesInfo.Types[arg]
		if tv.Value != nil || isCompiledSQL(pass, tv.Type) || forwards(pass, fd, fn, arg) {
			return
		}
		pass.Report(analysis.Diagnostic{Pos: arg.Pos(), Category: Name,
			Message: "FF-SP2 [sqlconst]: the SQL argument of " + fn.Name() + " is not a constant or a reportsql.CompiledSQL: use sqlc queries and bind parameters (§7)"})
		return
	}
}
